const oldCatalog = [...deepSpeciesCatalog, ...deepPredatorSpeciesCatalog, ...deepBenthicLifeSpeciesCatalog, ...deepHardLifeSpeciesCatalog];
const meshes = object => { const result = []; object.traverse(item => { if (item.isMesh) result.push(item); }); return result; };
function hashes(root) {
  root.updateMatrixWorld(true); const geometry = createHash('sha256'), pose = createHash('sha256'), material = createHash('sha256'), legacy = createHash('sha256');
  let count = 0, vertices = 0, triangles = 0;
  root.traverse(item => {
    pose.update(JSON.stringify({ name: item.name, type: item.type, matrix: item.matrix.toArray(), worldMatrix: item.matrixWorld.toArray() }));
    if (!item.isMesh) return; count++; vertices += item.geometry.attributes.position.count; triangles += (item.geometry.index?.count ?? item.geometry.attributes.position.count) / 3;
    for (const [name, a] of Object.entries(item.geometry.attributes).sort()) {
      const bytes = Buffer.from(a.array.buffer, a.array.byteOffset, a.array.byteLength); geometry.update(name);
      geometry.update(JSON.stringify({ itemSize: a.itemSize, normalized: a.normalized, type: a.array.constructor.name })); geometry.update(bytes); legacy.update(name); legacy.update(bytes);
    }
    if (item.geometry.index) { const a = item.geometry.index.array, bytes = Buffer.from(a.buffer, a.byteOffset, a.byteLength); geometry.update(bytes); legacy.update(bytes); }
    legacy.update(JSON.stringify(item.matrix.toArray()));
    for (const m of [].concat(item.material)) material.update(JSON.stringify({ type: m.type, color: m.color?.toArray(), emissive: m.emissive?.toArray(),
      emissiveIntensity: m.emissiveIntensity, roughness: m.roughness, metalness: m.metalness, side: m.side, transparent: m.transparent,
      opacity: m.opacity, depthWrite: m.depthWrite, vertexColors: m.vertexColors, flatShading: m.flatShading }));
  });
  return { geometry: geometry.digest('hex'), animationPose: pose.digest('hex'), materials: material.digest('hex'), legacyMeshDigest: legacy.digest('hex'), meshes: count, vertices, triangles };
}
function pose(root) { root.updateMatrixWorld(true); const result = []; root.traverse(p => result.push(p.matrix.toArray())); return result; }
function localPoints(root) {
  root.updateMatrixWorld(true); const inverse = root.matrixWorld.clone().invert(), result = [];
  for (const mesh of meshes(root)) for (let i = 0; i < mesh.geometry.attributes.position.count; i++) result.push(new THREE.Vector3()
    .fromBufferAttribute(mesh.geometry.attributes.position, i).applyMatrix4(mesh.matrixWorld).applyMatrix4(inverse));
  return result;
}

test('all ten original deep kits preserve exact complete native geometry, node animation, material and original factory source receipts', t => {
  for (const [path, expected] of Object.entries(originalSourceHashes)) assert.equal(createHash('sha256')
    .update(readFileSync(new URL(`../${path}`, import.meta.url))).digest('hex'), expected, path);
  const native = new DeepOceanAnimals(oldCatalog); t.after(() => native.dispose()); assert.equal(oldCatalog.length, 10);
  for (const frame of originalBaseline.frames) {
    const rows = structuredClone(frame.agents), before = structuredClone(rows);
    native.update(rows, originalBaseline.renderTimeSec, originalBaseline.renderOrigin); assert.equal(native.stats.activeAnimals, 10);
    for (const row of rows) assert.deepEqual(hashes(native.getObject(row.id)), frame.species[row.speciesId], `${row.speciesId}/${frame.input.label}`);
    assert.deepEqual(rows, before);
  }
});

